func uniquePaths(m int, n int) int {
	// 组合数 C(m+n-2, m-1)，用 Gamma 函数实现阶乘：n! = Γ(n+1)
	res := math.Gamma(float64(m+n-1)) / math.Gamma(float64(m)) / math.Gamma(float64(n))
	return int(math.Round(res))
}

func uniquePaths(m int, n int) int {
	cur := make([]int, n)
	for i := range cur {
		cur[i] = 1
	}
	for i := 1; i < m; i++ {
		for j := 1; j < n; j++ {
			cur[j] += cur[j-1]
		}
	}
	return cur[n-1]
}
